import type { MetricKey, Status } from '../config/thresholds'

export type NumericSample = Record<MetricKey, number>

/**
 * Where a value comes from:
 *  - `reported`  supplied by an external telemetry backend (WebSocket)
 *  - `modelled`  computed by this app from real NASA/NOAA inputs (e.g. a diurnal curve from InSight min/max)
 *  - `simulated` generated by the telemetry simulator; not a measurement
 *  - `measured`  measured on the crew member by a connected sensor
 *  - `self`      typed in or logged by the crew member
 *  - `device`    read from the device the dashboard runs on
 *  - `none`      no instrument is connected for this quantity, so there is no value
 */
export type DataOrigin = 'reported' | 'modelled' | 'simulated' | 'measured' | 'self' | 'device' | 'none'
export type Provenance = Partial<Record<MetricKey, DataOrigin>>

export interface Sample extends NumericSample {
  /** epoch ms */
  t: number
  iso: string
  /** Mission clock */
  sol: number
  utc: string
  /** Traverse state */
  distanceKm: number
  etaMin: number
  /** 0..1 progress along the traverse to the landing site */
  progress: number
  evaActive: boolean
  /** key currently being pushed out of range by the anomaly injector, if any */
  anomaly: MetricKey | null
  /** per-metric origin; metrics not listed are treated as simulated */
  provenance?: Provenance
}

/** `lost`: the alert ended because the value stopped arriving (sensor removed), not because it recovered */
export type AlertOutcome = 'resolved' | 'escalated' | 'de-escalated' | 'lost'

export interface Alert {
  id: number
  key: MetricKey
  level: Exclude<Status, 'normal'>
  value: number
  t: number
  /** when this alert stopped being the active one for its metric */
  resolvedAt?: number
  /** why it ended: back to normal, or replaced by a higher / lower level alert */
  outcome?: AlertOutcome
  /** id of the alert this one escalated / de-escalated from */
  previousId?: number
}

export interface TimelineEvent {
  id: number
  t: number
  key: MetricKey
  level: Exclude<Status, 'normal'> | 'resolved'
  label: string
}

export type Connection = 'connecting' | 'live' | 'lost'

/** Anything that can push telemetry samples: simulator, WebSocket, replay... */
export interface TelemetrySource {
  /** `backfill` samples are history and must not raise alerts */
  start(onSample: (s: Sample, backfill: boolean) => void): void
  stop(): void
  /** Dev hook (press "A"): force an anomaly now. Optional for real backends. */
  triggerAnomaly?(): void
  /**
   * True when samples are produced by a local timer. Browsers throttle timers in background tabs,
   * so a gap from such a source while the page is hidden is not a lost signal.
   */
  readonly timerDriven?: boolean
}
